        "6.1 Add Else Clause": "6.1 أضف Else Clause",
        "6.2 Create Enable & Disable Actions": "6.2 أنشئ إجراءي التفعيل والتعطيل",
        "6.3 Enter Reorder Mode": "6.3 ادخل وضع إعادة الترتيب",
        "6.4 Position Actions & Save": "6.4 رتّب الإجراءات واحفظ",
        "7-Day Completion Velocity": "سرعة الإنجاز خلال 7 أيام",
        "A bird flies past when you add a task.": "يمرّ طائر عند إضافة مهمة.",
        "A break stops at the day reset.": "تتوقف الاستراحة عند إعادة ضبط اليوم.",
        "A finished review costs credits even if your proof is rejected. Cancelling at the price preview costs nothing.": "المراجعة المكتملة تستهلك الرصيد حتى لو رُفض إثباتك. الإلغاء عند معاينة السعر لا يكلّف شيئًا.",
        "A passing test doesn't guarantee the real audit passes. AI verdicts can vary between runs.": "نجاح الاختبار لا يضمن نجاح التدقيق الحقيقي. قد تختلف أحكام الذكاء الاصطناعي بين مرة وأخرى.",
        "A reserved break has no fixed time. You set its length and the window in which you may start it. You then start it yourself, when you want, inside that window.": "الاستراحة المحجوزة ليس لها وقت ثابت. تحدد مدتها والنافذة التي يمكنك بدؤها فيها، ثم تبدؤها بنفسك متى شئت داخل تلك النافذة.",
        "A short leaf burst when you finish a task.": "انفجار أوراق قصير عند إنهاء مهمة.",
        "AI & Pro": "الذكاء الاصطناعي وبرو",
        "AI Proof Required": "يتطلب إثباتًا بالذكاء الاصطناعي",
        "AI Verified": "موثّقة بالذكاء الاصطناعي",
        "AI credits this 30-day cycle": "رصيد الذكاء الاصطناعي في دورة الـ 30 يومًا",
        "AI credits today": "رصيد الذكاء الاصطناعي اليوم",
        "AI provider": "مزوّد الذكاء الاصطناعي",
        "AI rates how clear a task's completion criteria are before it can be locked. It needs 7/10 or higher.": "يقيّم الذكاء الاصطناعي وضوح معايير إنجاز المهمة قبل قفلها. يلزم 7/10 أو أعلى.",
        "AI usage applies exactly like a real proof audit. There are no free tests. On Pro hosted AI you'll see a credit estimate before it runs; with your own API key, your provider bills this request and it counts toward your allowance.": "يُحتسب استخدام الذكاء الاصطناعي تمامًا مثل تدقيق إثبات حقيقي. لا توجد اختبارات مجانية. مع الذكاء الاصطناعي المستضاف في برو سترى تقدير الرصيد قبل التشغيل؛ ومع مفتاح API الخاص بك، يحاسبك مزوّدك على هذا الطلب ويُحتسب من حصتك.",
        "AI verification": "التحقق بالذكاء الاصطناعي",
        "AI with your own Gemini or Claude key (Copilot, criteria checks, proof reviews, notes)": "ذكاء اصطناعي بمفتاح Gemini أو Claude الخاص بك (المساعد الذكي، فحص المعايير، مراجعة الإثباتات، الملاحظات)",
        "About Mr. Study": "عن Mr. Study",
        "Access MacroDroid's global variable storage from the main menu.": "الوصول إلى مخزن المتغيرات العامة في MacroDroid من القائمة الرئيسية.",
        "Account": "الحساب",
        "Account & data": "الحساب والبيانات",
        "Account deletion": "حذف الحساب",
        "Action Blocked:": "الإجراء محظور:",
        "Activate 15m": "تفعيل 15 دقيقة",
        "Activate Emergency Bypass?": "تفعيل تجاوز الطوارئ؟",
        "Activate Pro": "تفعيل برو",
        "Active Total": "الإجمالي النشط",
        "Add a device": "إضافة جهاز",
        "Add a device first. The Bridge download has the new token built in, so it only works for the device you just added.": "أضف جهازًا أولًا. يحتوي تنزيل Bridge على الرمز الجديد، لذا يعمل فقط مع الجهاز الذي أضفته للتو.",
        "Add a key, test it, and see what strict checking does. · 7 steps": "أضف مفتاحًا، واختبره، وتعرّف على ما يفعله الفحص الصارم. · 7 خطوات",
        "Add device": "إضافة جهاز",
        "Add or replace key": "إضافة مفتاح أو استبداله",
        "Add tags to tasks, then filter your lists by them.": "أضف وسومًا إلى المهام، ثم صفِّ قوائمك بها.",
        "Add the Bearer token to authorize requests with your Taskitator sync engine.": "أضف رمز Bearer لتفويض الطلبات مع محرك مزامنة Taskitator.",
        "Add the backup's tasks to what you have. Nothing gets deleted.": "أضف مهام النسخة الاحتياطية إلى ما لديك. لا يُحذف شيء.",
        "Add them in the same planning window with + Add Reserved. Maximum 2 per day.": "أضفها في نافذة التخطيط نفسها عبر + إضافة محجوزة. بحد أقصى 2 يوميًا.",
        "Add up to 3 breaks with a start and end time. They can't overlap, and together they can't exceed your allowance.": "أضف حتى 3 استراحات بوقت بداية ونهاية. لا يمكن أن تتداخل، ولا أن يتجاوز مجموعها رصيدك.",
        "Alphabetical": "أبجدي",
        "Android Settings": "إعدادات Android",
        "Animals": "الحيوانات",
        "Animals inside the completion buttons. Off shows a plain tick.": "حيوانات داخل أزرار الإنجاز. عند الإيقاف تظهر علامة صح بسيطة.",
        "Anti-Lockout Protection:": "الحماية من القفل الدائم:",
