        "During these hours, your existing MacroDroid setup blocks your phone. Taskitator can stay closed. Emergency Bypass unlocks it temporarily; ordinary breaks do not override Sleep Lock.": "خلال هذه الساعات، يحجب إعداد MacroDroid الحالي هاتفك. يمكن أن يبقى Taskitator مغلقًا. تجاوز الطوارئ يفتحه مؤقتًا؛ أما الاستراحات العادية فلا تلغي قفل النوم.",
