        "Emergency Bypass unlocks protected tasks for 15 minutes. You get 4 a week, and they refill after your weekend.": "يفتح تجاوز الطوارئ المهام المحمية لمدة 15 دقيقة. لديك 4 أسبوعيًا، وتتجدد بعد عطلتك الأسبوعية.",
