        "Fig 1: Tap Macros at the bottom bar to view and manage macros.": "الشكل 1: اضغط Macros في الشريط السفلي لعرض الماكرو وإدارته.",
        "Fig 2: Enter App Blocker at (#1) and tap the red Triggers plus button at (#2).": "الشكل 2: أدخل App Blocker في (#1) واضغط زر الإضافة في Triggers الحمراء عند (#2).",
