        "Flexible Strict Mode (Settings → Day & week) raises the minimum length to 30–60 minutes and requires the same gap between one break's end and the next start.": "الوضع الصارم للمرنة (الإعدادات ← اليوم والأسبوع) يرفع الحد الأدنى للمدة إلى 30–60 دقيقة ويشترط الفاصل نفسه بين نهاية استراحة وبداية التالية.",
