        "Focus timer": "مؤقت التركيز",
        "Force Sync Now": "مزامنة فورية",
        "Free": "مجاني",
        "Free accounts can connect 3 devices, Pro accounts 12. If Pro ends, only your first 3 keep working and the rest show as revoked until you renew.": "يمكن للحسابات المجانية ربط 3 أجهزة، وحسابات برو 12 جهازًا. إذا انتهى برو، تبقى أول 3 أجهزة فقط عاملة ويظهر الباقي ملغى حتى تجدد.",
        "Free and Pro can both save a Gemini or Claude key. On Free it is the only way to use AI. On Pro you can switch between your key and hosted AI at any time without resetting hosted credits.": "يمكن للمجاني وبرو حفظ مفتاح Gemini أو Claude. في المجاني هو الطريقة الوحيدة لاستخدام الذكاء الاصطناعي. في برو يمكنك التبديل بين مفتاحك والذكاء الاصطناعي المستضاف في أي وقت دون إعادة ضبط الرصيد المستضاف.",
        "Free covers task management, breaks, phone lock and AI with your own key. Pro adds hosted AI, batch reviews, Dynamic Priority, Study plans and more.": "المجاني يشمل إدارة المهام والاستراحات وقفل الهاتف والذكاء الاصطناعي بمفتاحك. برو يضيف الذكاء الاصطناعي المستضاف والمراجعات الجماعية والأولوية الديناميكية وخطط الدراسة والمزيد.",
        "Fri": "الجمعة",
