        "How Taskitator handles your data, AI keys and account.": "كيف يتعامل Taskitator مع بياناتك ومفاتيح الذكاء الاصطناعي وحسابك.",
        "How Taskitator looks, sounds and syncs.": "مظهر Taskitator وأصواته ومزامنته.",
        "How long the distraction note stays open before it saves and closes itself.": "مدة بقاء ملاحظة التشتت مفتوحة قبل أن تُحفظ وتُغلق تلقائيًا.",
        "How loud the Pomodoro and focus-timer sounds are on this device. Release the slider to hear it.": "مستوى صوت Pomodoro ومؤقت التركيز على هذا الجهاز. اترك المنزلق لتسمعه.",
        "How to use each feature": "كيف تستخدم كل ميزة",
        "How your key is stored": "كيف يُخزَّن مفتاحك",
        "I've turned off every Taskitator blocking macro on all my devices.": "أوقفت كل ماكرو حجب لـ Taskitator على كل أجهزتي.",
        "If a Scheduled break begins before it finishes, it is cut off there. The rest is gone for the day, not refunded or moved.": "إذا بدأت استراحة مجدولة قبل انتهائها، تُقطع عندها. يضيع الباقي لهذا اليوم، ولا يُعاد ولا يُنقل.",
        "If the window ends before you start it, that allowance is gone for the day.": "إذا انتهت النافذة قبل أن تبدأها، يضيع ذلك الرصيد لهذا اليوم.",
        "Import an older Taskitator account": "استيراد حساب Taskitator قديم",
        "Import each macro (do this for both the App Blocker and the Cloud Bridge):": "استورد كل ماكرو (افعل ذلك لـ App Blocker و Cloud Bridge):",
        "Import older account": "استيراد حساب قديم",
        "Import the Bridge (the token-ready one from Settings, or the no-token one above).": "استورد Bridge (الجاهز بالرمز من الإعدادات، أو الذي بدون رمز أعلاه).",
        "Import the macros": "استيراد الماكرو",
        "Import the ready-made App Blocker and Cloud Bridge. The token can be built in from Settings.": "استورد App Blocker و Cloud Bridge الجاهزين. يمكن تضمين الرمز من الإعدادات.",
        "In Enter url, paste your Status URL from the Settings page.": "في Enter url، الصق رابط الحالة (Status URL) من صفحة الإعدادات.",
