        "Included. Allowance comes from your Pro license": "مشمول. الحصة من ترخيص برو",
        "Included. Credit estimate shown first; no free tests": "مشمول. يظهر تقدير الرصيد أولًا؛ لا اختبارات مجانية",
        "Included. Join up to 2 Universes.": "مشمول. انضم إلى حتى 2 من مساحات يونيفيرس.",
        "Included. Join up to 7 Universes.": "مشمول. انضم إلى حتى 7 من مساحات يونيفيرس.",
        "Included. Uses AI like a real audit; no free tests": "مشمول. يستخدم الذكاء الاصطناعي كتدقيق حقيقي؛ لا اختبارات مجانية",
        "Inherit Criteria from Sibling": "وراثة المعايير من مهمة شقيقة",
        "Install MacroDroid and find your way around": "ثبّت MacroDroid وتعرّف على واجهته",
        "Keep MacroDroid and the browser you use for Taskitator out of the blocked-app list so you can manage the setup. The Cloud Bridge does not choose or change blocked apps.": "أبقِ MacroDroid والمتصفح الذي تستخدمه لـ Taskitator خارج قائمة التطبيقات المحجوبة لتتمكن من إدارة الإعداد. لا يختار Cloud Bridge التطبيقات المحجوبة ولا يغيّرها.",
        "Keep screen awake": "إبقاء الشاشة مضاءة",
        "Key storage isn't set up on the server yet.": "تخزين المفاتيح غير مُعدّ على الخادم بعد.",
        "Keys are encrypted on Taskitator's server. Showing, copying, replacing or deleting a key asks for your password (or Google sign-in) first. AI requests go through Taskitator's server to the provider you picked.": "المفاتيح مشفّرة على خادم Taskitator. عرض المفتاح أو نسخه أو استبداله أو حذفه يطلب كلمة المرور (أو تسجيل الدخول بـ Google) أولًا. تمر طلبات الذكاء الاصطناعي عبر خادم Taskitator إلى المزوّد الذي اخترته.",
