        "Make sure both macros are enabled. The Bridge then enables or disables the App Blocker for you.": "تأكد أن الماكرو كليهما مفعّل. بعدها يفعّل Bridge أو يعطّل App Blocker نيابة عنك.",
        "Make the selected tasks bonus or required. Tasks that can't change (shield-protected required work) are skipped.": "اجعل المهام المحددة إضافية أو مطلوبة. المهام التي لا يمكن تغييرها (العمل المطلوب المحمي) تُتخطى.",
        "Manage account & password": "إدارة الحساب وكلمة المرور",
