        "On your other devices, clear Taskitator's site data yourself, and delete any downloaded backups you don't need. Creating a new account won't bring deleted data back.": "على أجهزتك الأخرى، امسح بيانات موقع Taskitator بنفسك، واحذف أي نسخ احتياطية منزّلة لا تحتاجها. إنشاء حساب جديد لن يعيد البيانات المحذوفة.",
