        "Optional Note / Clarification:": "ملاحظة / توضيح اختياري:",
        "Outside these hours, your normal task and Universe blocking rules apply. Your phone needs internet and MacroDroid’s regular status checks.": "خارج هذه الساعات، تنطبق قواعد حجب المهام ويونيفيرس المعتادة. يحتاج هاتفك إلى الإنترنت وإلى فحوصات الحالة المنتظمة من MacroDroid.",
        "Parallax": "المنظور المتحرك",
        "Password": "كلمة المرور",
        "Pending Today": "المعلّقة اليوم",
        "Performance sync with today's scheduled recovery windows.": "مقارنة الأداء مع نوافذ الاستراحة المجدولة لهذا اليوم.",
        "Permanently deletes finished and trashed tasks, plus their reference files. Active tasks stay.": "يحذف نهائيًا المهام المنجزة والمحذوفة مع ملفاتها المرجعية. المهام النشطة تبقى.",
        "Permanently deletes your account, cloud data, saved AI keys and login. This can't be undone.": "يحذف نهائيًا حسابك وبياناتك السحابية ومفاتيح الذكاء الاصطناعي المحفوظة وبيانات الدخول. لا يمكن التراجع عن ذلك.",
        "Ph2_S10: Conditions/Loops → If clause": "Ph2_S10: Conditions/Loops ← If clause",
