        "Phone lock": "قفل الهاتف",
        "Phone lock (MacroDroid)": "قفل الهاتف (MacroDroid)",
        "Pick 30 min, 45 min, 1 hour, a custom length, or until your allowance ends.": "اختر 30 دقيقة أو 45 دقيقة أو ساعة أو مدة مخصصة أو حتى نفاد رصيدك.",
        "Pick a .json file you downloaded from Taskitator.": "اختر ملف .json نزّلته من Taskitator.",
        "Pick one way to set up the App Blocker and the bridge that turns it on and off.": "اختر طريقة واحدة لإعداد App Blocker و Bridge الذي يشغّله ويوقفه.",
        "Plain Text (.txt)": "نص عادي (.txt)",
        "Planning": "التخطيط",
        "Play a sound when you finish a task or your proof is approved.": "شغّل صوتًا عند إنهاء مهمة أو قبول إثباتك.",
        "Pomodoro volume": "مستوى صوت Pomodoro",
        "Postpone your saved bedtime by 30 or 60 minutes, once per night across all devices. Wake-up time stays the same. An overnight schedule uses the date its bedtime starts, so midnight does not give you another delay. Other task locks still apply.": "أجّل وقت نومك المحفوظ 30 أو 60 دقيقة، مرة واحدة في الليلة على كل الأجهزة. يبقى وقت الاستيقاظ كما هو. الجدول الليلي يستخدم تاريخ بدء وقت النوم، لذا لا يمنحك منتصف الليل تأجيلًا آخر. أقفال المهام الأخرى تبقى سارية.",
        "Powers Copilot, criteria checks, proof reviews and note extraction. Gemini and Claude each keep their own key, so switching never erases one.": "يشغّل المساعد الذكي وفحص المعايير ومراجعة الإثباتات واستخراج الملاحظات. يحتفظ Gemini و Claude كلٌّ بمفتاحه، لذا لا يمسح التبديل أيًّا منهما.",
        "Prefer manual setup? Continue to the full guide below →": "تفضّل الإعداد اليدوي؟ تابع إلى الدليل الكامل أدناه ←",
        "Press Save schedule. Saved minutes are taken from your allowance immediately.": "اضغط حفظ الجدول. تُخصم الدقائق المحفوظة من رصيدك فورًا.",
        "Press Start planning. The 10 minutes start at that moment. You can start it until 6 hours before the day resets.": "اضغط بدء التخطيط. تبدأ الدقائق العشر من تلك اللحظة. يمكنك البدء حتى 6 ساعات قبل إعادة ضبط اليوم.",
        "Press Start planning. You get 10 minutes to enter your breaks.": "اضغط بدء التخطيط. لديك 10 دقائق لإدخال استراحاتك.",
        "Prevents completing this task until all subtasks beneath it are completely finished.": "يمنع إكمال هذه المهمة حتى تنتهي كل المهام الفرعية تحتها تمامًا.",
        "Priorities": "الأولويات",
        "Priority": "الأولوية",
        "Privacy & deletion": "الخصوصية والحذف",
        "Privacy & terms": "الخصوصية والشروط",
        "Privacy policy ↗": "سياسة الخصوصية ↗",
        "Pro uses Taskitator AI without a key. Your daily and 30-day allowance comes from your Pro license and is shown in Settings. Daily limits reset at midnight Asia/Riyadh. Every charge is rounded up to the next 0.5 credit.": "برو يستخدم ذكاء Taskitator الاصطناعي بدون مفتاح. حصتك اليومية وحصة الـ 30 يومًا من ترخيص برو وتظهر في الإعدادات. الحدود اليومية تتجدد عند منتصف الليل بتوقيت الرياض. كل خصم يُقرَّب إلى أعلى 0.5 رصيد.",
        "Productivity Statistics": "إحصائيات الإنتاجية",
