        "Reload the page when changes arrive from another device. Turning this off doesn't stop syncing.": "أعد تحميل الصفحة عند وصول تغييرات من جهاز آخر. إيقاف هذا لا يوقف المزامنة.",
        "Remove all devices": "إزالة كل الأجهزة",
