        "Reviewing several tasks together is one combined request and usually costs less than reviewing them one by one. When proof is insufficient you pay half the real usage, rounded up to the next 0.5.": "مراجعة عدة مهام معًا طلب واحد مجمّع، وغالبًا تكلّف أقل من مراجعتها واحدة تلو الأخرى. عندما يكون الإثبات غير كافٍ تدفع نصف الاستخدام الفعلي، مقرّبًا إلى أعلى 0.5.",
        "Reviewing several tasks together usually costs less than reviewing them one by one.": "مراجعة عدة مهام معًا غالبًا تكلّف أقل من مراجعتها واحدة تلو الأخرى.",
