        "Saved on its own, so you don't need to press Save changes. Google sign-in brings you back here to paste it.": "يُحفظ وحده، فلا حاجة للضغط على حفظ التغييرات. تسجيل الدخول بـ Google يعيدك إلى هنا للصقه.",
        "Saves your tasks, projects, settings, breaks, saved criteria and review history from this browser as one .json file.": "يحفظ مهامك ومشاريعك وإعداداتك واستراحاتك ومعاييرك المحفوظة وسجل المراجعات من هذا المتصفح في ملف .json واحد.",
        "Saving reserves allowance; locking Scheduled disables Flexible for the day.": "الحفظ يحجز من الرصيد؛ وقفل المجدولة يعطّل المرنة لهذا اليوم.",
