        "Select a due date for all selected tasks. Overdue AI-locked tasks are guarded against postponement.": "اختر تاريخ استحقاق لكل المهام المحددة. المهام المتأخرة المقفلة بالذكاء الاصطناعي محمية من التأجيل.",
        "Select a pre-verified template. These templates are already validated.": "اختر قالبًا موثّقًا مسبقًا. هذه القوالب مُتحقق منها بالفعل.",
        "Select a priority rank to assign directly to each selected task.": "اختر رتبة أولوية لتعيينها مباشرة لكل مهمة محددة.",
        "Select a sibling with verified criteria...": "اختر مهمة شقيقة ذات معايير موثّقة...",
        "Select a target date to move all eligible, non-locked overdue tasks in bulk.": "اختر تاريخًا لنقل كل المهام المتأخرة المؤهلة غير المقفلة دفعة واحدة.",
        "Select all": "تحديد الكل",
        "Select restricted distracting apps under Application Launched.": "اختر التطبيقات المشتتة المقيدة تحت Application Launched.",
        "Selected weekdays": "أيام الأسبوع المحددة",
        "Send a sample proof to see how the AI auditor reads this criteria. The test uses the exact same audit as a real proof and returns the same verdicts. It doesn't save, complete or lock the task.": "أرسل إثباتًا تجريبيًا لترى كيف يقرأ مدقق الذكاء الاصطناعي هذه المعايير. يستخدم الاختبار التدقيق نفسه للإثبات الحقيقي ويعطي الأحكام نفسها. لا يحفظ المهمة ولا يكملها ولا يقفلها.",
        "Server response": "استجابة الخادم",
        "Sessions before large break": "الجلسات قبل الاستراحة الطويلة",
        "Set up AI": "إعداد الذكاء الاصطناعي",
        "Set up the endpoint details and enforce synchronous execution.": "اضبط تفاصيل نقطة الاتصال وافرض التنفيذ المتزامن.",
        "Set up your workspace": "جهّز مساحة عملك",
        "Shielded Parent": "أصل محمي",
        "Short guided tours of the app. Replay any of them whenever you like.": "جولات تعريفية قصيرة بالتطبيق. أعد تشغيل أي منها متى شئت.",
        "Short vibrations when you tap buttons or finish tasks. Android phones only.": "اهتزازات قصيرة عند الضغط على الأزرار أو إنهاء المهام. لهواتف Android فقط.",
        "Show": "عرض",
        "Show matching tasks. Parent tasks remain visible for context.": "اعرض المهام المطابقة. تبقى المهام الأصلية ظاهرة للسياق.",
        "Sign in": "تسجيل الدخول",
        "Sign in and connect your account to manage your break limits.": "سجّل الدخول واربط حسابك لإدارة حدود استراحاتك.",
        "Sign in to open your tasks, or create an account to get started.": "سجّل الدخول لفتح مهامك، أو أنشئ حسابًا للبدء.",
        "Sign in with Google": "تسجيل الدخول بـ Google",
