        "Start timer": "تشغيل المؤقت",
        "Start window: at least 5 minutes wide, inside today, not already over. It can't overlap a Scheduled break or another reserved window.": "نافذة البدء: 5 دقائق على الأقل، داخل اليوم، ولم تنتهِ بعد. لا يمكن أن تتداخل مع استراحة مجدولة أو نافذة محجوزة أخرى.",
