        "Submit AI Verification Proof": "إرسال إثبات التحقق بالذكاء الاصطناعي",
        "Submit Proof": "إرسال الإثبات",
        "Submitting proof consumes your AI usage. If your proof is rejected because it fails the task criteria or is invalid, token usage is still calculated and consumed—no refunds are issued. Make sure your proof is clear and complete before submitting.": "إرسال الإثبات يستهلك من استخدامك للذكاء الاصطناعي. إذا رُفض إثباتك لأنه لا يحقق معايير المهمة أو غير صالح، يُحتسب استهلاك الرموز ويُخصم، ولا يُسترد. تأكد أن إثباتك واضح وكامل قبل الإرسال.",
        "Subtasks Under This Task": "المهام الفرعية تحت هذه المهمة",
        "Sun": "الأحد",
        "Sunday": "الأحد",
        "Swipe up the \"Local Variables\" drawer and select \"user token\".": "اسحب درج \"Local Variables\" للأعلى واختر \"user token\".",
        "Sync": "المزامنة",
        "Sync Status Guide": "دليل حالة المزامنة",
        "Sync now": "مزامنة الآن",
        "Synced": "متزامن",
        "TASKITATOR FREE & PRO": "TASKITATOR المجاني وبرو",
        "Tags": "الوسوم",
        "Tags, priorities, checks": "الوسوم، الأولويات، الفحوصات",
        "Tap Macros tab and open a new macro creation screen.": "اضغط تبويب Macros وافتح شاشة إنشاء ماكرو جديد.",
        "Tap the blue Actions plus button to add response behavior.": "اضغط زر إضافة Actions الأزرق لإضافة سلوك الاستجابة.",
        "Tap the bottom-right checkmark button to save your completed Cloud Bridge macro.": "اضغط زر علامة الصح أسفل اليمين لحفظ ماكرو Cloud Bridge المكتمل.",
        "Tap the checkmark in the bottom-right corner to save your App Blocker macro.": "اضغط علامة الصح في الزاوية السفلية اليمنى لحفظ ماكرو App Blocker.",
        "Target Date": "التاريخ المستهدف",
        "Target Due Date": "تاريخ الاستحقاق المستهدف",
