        "Criteria Error: Unresolved variable placeholder(s) detected: {{0}}. Please define all referenced variables in the task title using the format: Task Title {{1}==value}.": "خطأ في المعايير: اكتُشفت متغيرات غير محلولة: {{0}}. عرّف كل المتغيرات المشار إليها في عنوان المهمة بالصيغة: Task Title {{1}==value}.",
