        "Exports exclude credentials, balances, memberships and phone-blocking consent. Other members’ proof attachments require permission from their author. Import replaces this Universe’s projects and tasks and resets live progress, submissions, approvals and task discussions. Membership and roles stay as they are. Export your current Universe first if you may need to recover it.": "لا تشمل التصديرات بيانات الاعتماد والأرصدة والعضويات وموافقة حجب الهاتف. مرفقات إثبات الأعضاء الآخرين تتطلب إذن أصحابها. الاستيراد يستبدل مشاريع يونيفيرس هذا ومهامه ويعيد ضبط التقدم الحي والإرسالات والاعتمادات ونقاشات المهام. تبقى العضوية والأدوار كما هي. صدّر يونيفيرس الحالي أولًا إذا كنت قد تحتاج استعادته.",
