        "February": "فبراير",
        "File exceeds maximum size of 5 MB ({0} MB).": "الملف يتجاوز الحجم الأقصى 5 ميغابايت ({0} ميغابايت).",
        "File is too large ({0} MB). Maximum allowed is 5 MB.": "الملف كبير جدًا ({0} ميغابايت). الحد الأقصى المسموح 5 ميغابايت.",
        "File size ({0} MB) exceeds the {1} MB upload limit.": "حجم الملف ({0} ميغابايت) يتجاوز حد الرفع {1} ميغابايت.",
        "Files must be 1 byte to 5 MiB.": "يجب أن يكون حجم الملفات من 1 بايت إلى 5 ميغابايت.",
        "Filter tasks": "تصفية المهام",
        "Finish planning before starting a reserved break.": "أنهِ التخطيط قبل بدء استراحة محجوزة.",
        "Finish syncing your task changes before submitting proof.": "أكمل مزامنة تغييرات مهامك قبل إرسال الإثبات.",
        "Finish, move, or trash all required tasks due today or overdue before viewing or extracting notes.": "أكمل كل المهام المطلوبة المستحقة اليوم أو المتأخرة، أو انقلها، أو احذفها قبل عرض الملاحظات أو استخراجها.",
        "First, confirm it's you with your password or the Google account linked to this login. Each confirmation covers this one action.": "أولًا، أكّد هويتك بكلمة المرور أو بحساب Google المرتبط بهذا الحساب. كل تأكيد يغطي هذا الإجراء وحده.",
        "Flexible Breaks, {0} of allowance left, no break active": "الاستراحات المرنة، متبقٍ {0} من الرصيد، لا توجد استراحة نشطة",
        "Flexible Strict Mode": "الوضع الصارم للمرنة",
        "Flexible Strict Mode needs {0} minutes between breaks. You can start again in {1} min.": "الوضع الصارم للمرنة يتطلب {0} دقيقة بين الاستراحات. يمكنك البدء مجددًا بعد {1} دقيقة.",
        "Flexible Strict Mode needs {0} minutes between breaks. Your next break can start at {1}.": "الوضع الصارم للمرنة يتطلب {0} دقيقة بين الاستراحات. يمكن أن تبدأ استراحتك التالية عند {1}.",
        "Flexible Strict Mode requires at least {0} minutes.": "الوضع الصارم للمرنة يتطلب {0} دقيقة على الأقل.",
        "Flexible breaks": "الاستراحات المرنة",
        "Flexible breaks can’t be ended before your minimum, shorter presets are unavailable, and the same amount of time must pass before your next break.": "لا يمكن إنهاء الاستراحات المرنة قبل حدك الأدنى، والمدد الجاهزة الأقصر غير متاحة، ويجب أن تمر المدة نفسها قبل استراحتك التالية.",
        "Focus Session": "جلسة تركيز",
        "Focus Session {0} of {1}": "جلسة تركيز {0} من {1}",
        "Follow the guide": "اتبع الدليل",
        "For real emergencies only. It lifts your restrictions for **15 minutes**, and you get **4 per week**. They refill after the weekend.": "للطوارئ الحقيقية فقط. يرفع قيودك لمدة **15 دقيقة**، ولديك **4 أسبوعيًا**. تتجدد بعد العطلة الأسبوعية.",
        "For your security, sign in again after this long away. Your unsynced changes are kept on this device.": "لأمانك، سجّل الدخول مجددًا بعد هذا الغياب الطويل. تغييراتك غير المتزامنة محفوظة على هذا الجهاز.",
        "Forget to plan on a covered day with no plan and you get **zero breaks**. Days marked “Not covered” keep the normal rules": "إذا نسيت التخطيط في يوم مشمول بلا خطة فستحصل على **صفر استراحات**. الأيام المعلّمة \"غير مشمول\" تبقى بالقواعد العادية",
        "Free accounts use AI with their own API key, within a daily and monthly allowance.": "الحسابات المجانية تستخدم الذكاء الاصطناعي بمفتاح API الخاص بها، ضمن حصة يومية وشهرية.",
        "Free covers tasks, breaks, phone rules and Copilot with your own key. Pro adds:": "المجاني يشمل المهام والاستراحات وقواعد الهاتف والمساعد الذكي بمفتاحك. برو يضيف:",
        "Free: needed for Copilot and proof checks. Pro: already included": "المجاني: مطلوب للمساعد الذكي وفحص الإثباتات. برو: مشمول بالفعل",
        "Full screen is unavailable in this browser.": "ملء الشاشة غير متاح في هذا المتصفح.",
        "Gemini API HTTP {0}": "Gemini API HTTP {0}",
        "General discussion": "نقاش عام",
        "Generate dates": "توليد التواريخ",
