        "Generate the schedule first.": "ولّد الجدول أولًا.",
        "Get review quote": "احصل على عرض سعر المراجعة",
        "Google AI Studio.": "Google AI Studio.",
        "Google confirmation URL is missing or invalid. Check the Worker Google OAuth settings in pro/verification-setup.html, then retry or cancel.": "رابط تأكيد Google مفقود أو غير صالح. تحقق من إعدادات Google OAuth في Worker داخل pro/verification-setup.html، ثم أعد المحاولة أو ألغِ.",
        "Google confirmation failed or was cancelled. Use the Google account already connected to this login and try again.": "فشل تأكيد Google أو أُلغي. استخدم حساب Google المرتبط بهذا الحساب وحاول مجددًا.",
        "Google identity confirmed. Check the blocker confirmation and manually type the phrase.": "تم تأكيد هوية Google. تحقق من تأكيد الحاجب واكتب العبارة يدويًا.",
        "Google sign-in confirmed. Finish within 5 minutes. If you're adding a key, paste it now.": "تم تأكيد تسجيل الدخول بـ Google. أنهِ خلال 5 دقائق. إذا كنت تضيف مفتاحًا، فالصقه الآن.",
        "Google sign-in was cancelled or failed. Try again with the Google account linked to this login.": "أُلغي تسجيل الدخول بـ Google أو فشل. حاول مجددًا بحساب Google المرتبط بهذا الحساب.",
        "Group Shared credits": "رصيد المجموعة المشترك",
