        "Identity verified. Check the blocker confirmation and manually type the phrase. Verification expires after five minutes.": "تم التحقق من الهوية. تحقق من تأكيد الحاجب واكتب العبارة يدويًا. ينتهي التحقق بعد خمس دقائق.",
        "If a Scheduled break begins before it finishes, the remaining time is revoked for today.": "إذا بدأت استراحة مجدولة قبل انتهائها، يُلغى الوقت المتبقي لهذا اليوم.",
        "If phone lock is active, your device stays locked until verified by AI proof.": "إذا كان قفل الهاتف نشطًا، يبقى جهازك مقفلًا حتى يتحقق الذكاء الاصطناعي من الإثبات.",
        "If the receipt is not found, do not assume deletion succeeded. Sign in to check your account or contact Mazendev.": "إذا لم يُعثر على الإيصال، فلا تفترض نجاح الحذف. سجّل الدخول للتحقق من حسابك أو تواصل مع Mazendev.",
        "If the request timed out, refresh key status before trying again.": "إذا انتهت مهلة الطلب، حدّث حالة المفتاح قبل المحاولة مجددًا.",
        "If the request timed out, use Check deletion status before trying again.": "إذا انتهت مهلة الطلب، استخدم \"التحقق من حالة الحذف\" قبل المحاولة مجددًا.",
        "If you haven’t chosen a break system by the deadline, Scheduled locks for the day with that weekday’s plan. On a covered day without a plan, that means": "إذا لم تختر نظام استراحات قبل الموعد النهائي، تُقفل المجدولة لهذا اليوم بخطة ذلك اليوم من الأسبوع. وفي يوم مشمول بلا خطة، يعني ذلك",
