        "Once created, AI-Checked tasks CANNOT be edited (except description/tags) and CANNOT be deleted.": "بعد الإنشاء، لا يمكن تعديل المهام المفحوصة بالذكاء الاصطناعي (عدا الوصف والوسوم) ولا يمكن حذفها.",
