        "Use **＋** to add a task. Task editors pick tags and priorities from your Universe’s labels. If you have no project yet, create one first.": "استخدم **＋** لإضافة مهمة. يختار محررو المهام الوسوم والأولويات من تسميات يونيفيرس. إذا لم يكن لديك مشروع بعد، فأنشئ واحدًا أولًا.",
        "Use 3–20 letters, numbers or underscores. Uppercase and lowercase versions count as the same username.": "استخدم 3–20 حرفًا أو رقمًا أو شرطة سفلية. الأحرف الكبيرة والصغيرة تُعد اسم المستخدم نفسه.",
