        "When Flexible is in use, the button shows how much allowance is left and says **On break** while one is running:": "عند استخدام المرنة، يعرض الزر الرصيد المتبقي ويقول **في استراحة** أثناء استراحة جارية:",
        "When on, the AI checks your proof against the task’s criteria before the task locks as done.": "عند التفعيل، يفحص الذكاء الاصطناعي إثباتك وفق معايير المهمة قبل قفلها كمنجزة.",
        "When your day starts, your weekend and break limits": "متى يبدأ يومك، وعطلتك الأسبوعية، وحدود الاستراحات",
        "With **Taskitator Pro**, Copilot, proof checks and criteria validation work right away on Taskitator AI. No key needed. The steps below are only for using **your own key**.": "مع **Taskitator برو**، يعمل المساعد الذكي وفحص الإثباتات والتحقق من المعايير فورًا بذكاء Taskitator الاصطناعي. لا حاجة لمفتاح. الخطوات أدناه فقط لاستخدام **مفتاحك الخاص**.",
        "With a {0}-minute minimum and a {1} daily maximum, you get at most {2} Flexible break{3} a day.": "بحد أدنى {0} دقيقة وحد يومي {1}، تحصل على {2} استراحة مرنة كحد أقصى يوميًا.",
