        "You are signed in. Your tasks stay with this account.": "أنت مسجّل الدخول. تبقى مهامك مع هذا الحساب.",
        "You can change phone access once today's tasks are done, during a scheduled break, or while Emergency Bypass is on.": "يمكنك تغيير الوصول للهاتف بعد إنجاز مهام اليوم، أو أثناء استراحة مجدولة، أو أثناء تفعيل تجاوز الطوارئ.",
