        "Your Free personal-key AI allowance is used up. It refills at midnight (Riyadh time) each day and on the 1st of each month.": "نفدت حصة الذكاء الاصطناعي المجانية بمفتاحك الشخصي. تتجدد عند منتصف الليل (بتوقيت الرياض) يوميًا وفي أول كل شهر.",
