        "Your Taskitator Pro license is not active. Existing Dynamic Priority settings are kept, but they can only be turned off.": "ترخيص Taskitator برو غير نشط. إعدادات الأولوية الديناميكية الحالية محفوظة، لكن يمكن إيقافها فقط.",
